// FIKRA STUDIO V3.0 — Real Audio Envelope Visualizer (Fixes ISS-003)
// Accepts real per-frame RMS envelope generated by `fikra_v3.media_intelligence` (FFmpeg).
// Never misrepresents synthetic sine waves as real audio measurements.
import React from 'react';
import { useCurrentFrame } from 'remotion';
import { FIKRA_COLORS } from '../utils/rtl';

export interface AudioSpectrumBarProps {
  bars?: number;
  color?: string;
  height?: number;
  /** Real per-frame normalized RMS envelope [0..1] from FFmpeg analysis. */
  envelope?: number[];
  /** Explicit mode label: 'real_audio' when envelope is provided, 'preview_only' otherwise. */
  mode?: 'real_audio' | 'preview_only';
}

export const AudioSpectrumBar: React.FC<AudioSpectrumBarProps> = ({
  bars = 24,
  color = FIKRA_COLORS.quranGold,
  height = 72,
  envelope,
  mode,
}) => {
  const frame = useCurrentFrame();
  const hasRealAudio = Array.isArray(envelope) && envelope.length > 0;
  const activeMode = mode ?? (hasRealAudio ? 'real_audio' : 'preview_only');

  return (
    <div
      data-audio-mode={activeMode}
      style={{
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        gap: 6,
        height,
      }}
    >
      {Array.from({ length: bars }).map((_, i) => {
        let level = 0.2;
        if (hasRealAudio && activeMode === 'real_audio') {
          const offset = Math.max(0, Math.min(envelope.length - 1, frame + (i - Math.floor(bars / 2))));
          level = Math.max(0.08, Math.min(1.0, envelope[offset] ?? 0.1));
        } else {
          // Honest static neutral bar curve when no audio file has been analyzed yet
          const distFromCenter = Math.abs(i - (bars - 1) / 2) / Math.max(1, bars / 2);
          level = Math.max(0.15, 0.45 - distFromCenter * 0.25);
        }
        const barH = Math.max(10, Math.round(level * height));
        return (
          <div
            key={i}
            style={{
              width: 6,
              height: barH,
              borderRadius: 999,
              backgroundColor: color,
              opacity: hasRealAudio ? 0.8 + 0.2 * level : 0.45,
            }}
          />
        );
      })}
    </div>
  );
};
